        impl Footer { # [doc = " Keys for registered claims in the footer, that are reserved for usage by PASETO in top-level."] pub const REGISTERED_CLAIMS : [& 'static str ; 2] = ["kid" , "wpk"] ; # [doc = " All PASERK types that are (implemented in this library) unsafe in the footer."] pub const DISALLOWED_FOOTER : [& 'static str ; 8] = ["k2.local." , "k4.local." , "k2.secret." , "k3.secret." , "k4.secret." , "k2.public." , "k3.public." , "k4.public." ,] ; # [doc = " See [PASETO docs] for the reason behind this limit."] # [doc = ""] # [doc = " Maximum number of named keys within an object."] # [doc = ""] # [doc = " [PASETO docs]: https://github.com/paseto-standard/paseto-spec/blob/master/docs/02-Implementation-Guide/01-Payload-Processing.md#enforcing-maximum-depth-without-parsing-the-json-string"] pub const DEFAULT_MAX_KEYS : usize = 512 ; # [doc = " See [PASETO docs] for the reason behind this limit."] # [doc = ""] # [doc = " Maximum length of the JSON-encoded string."] # [doc = ""] # [doc = " [PASETO docs]: https://github.com/paseto-standard/paseto-spec/blob/master/docs/02-Implementation-Guide/01-Payload-Processing.md#enforcing-maximum-depth-without-parsing-the-json-string"] pub const DEFAULT_MAX_LEN : usize = 8192 ; # [doc = " See [PASETO docs] for the reason behind this limit."] # [doc = ""] # [doc = " This value has been set by `serde_json` and cannot be changed."] # [doc = ""] # [doc = " [PASETO docs]: https://github.com/paseto-standard/paseto-spec/blob/master/docs/02-Implementation-Guide/01-Payload-Processing.md#enforcing-maximum-depth-without-parsing-the-json-string"] pub const MAX_RECURSION_DEPTH : usize = 128 ; # [doc = " Create a new `Footer` instance."] pub fn new () -> Self { Self { list_of : HashMap :: new () , max_keys : Self :: DEFAULT_MAX_KEYS , max_len : Self :: DEFAULT_MAX_LEN , } } # [doc = " Change the default (512) amount of maximum number of named keys within an object."] # [doc = ""] # [doc = " __NOTE__: There should be no need to change this if you don't know this is a specific problem for you."] pub fn max_keys (& mut self , max_keys : usize) { self . max_keys = max_keys ; } # [doc = " Change the default (8192) amount of maximum number of named keys within an object."] # [doc = ""] # [doc = " __NOTE__: There should be no need to change this if you don't know this is a specific problem for you."] pub fn max_len (& mut self , max_len : usize) { self . max_len = max_len ; } # [doc = " Add additional claims. If `claim` already exists, it is replaced with the new."] # [doc = ""] # [doc = " Errors:"] # [doc = " - `claim` is a reserved claim (see [`Self::REGISTERED_CLAIMS`])"] # [doc = " - `value` is any of (starts with) the disallowed PASERK types (see [`Self::DISALLOWED_FOOTER`])."] pub fn add_additional (& mut self , claim : & str , value : & str) -> Result < () , Error > { for unsafe_value in Self :: DISALLOWED_FOOTER { if value . starts_with (unsafe_value) { return Err (Error :: InvalidClaim) ; } } if ! Self :: REGISTERED_CLAIMS . contains (& claim) { self . list_of . insert (claim . into () , value . into ()) ; Ok (()) } else { Err (Error :: InvalidClaim) } } # [doc = " Checks whether a specific claim has been added to the list."] # [doc = ""] # [doc = " E.g `contains_claim(\"kid\") == true` if `kid` has been added before."] pub fn contains_claim (& self , claim : & str) -> bool { self . list_of . contains_key (claim) } # [doc = " Return Some(claim value) if claims list contains the `claim`."] # [doc = " None otherwise."] pub fn get_claim (& self , claim : & str) -> Option < & Value > { self . list_of . get (claim) } # [cfg (feature = "paserk")] # [doc = " Set the `kid` claim. If it already exists, replace it with the new."] pub fn key_id (& mut self , id : & Id) { let mut paserk_kid = String :: new () ; id . fmt (& mut paserk_kid) . unwrap () ; self . list_of . insert ("kid" . into () , paserk_kid . into ()) ; } # [doc = " Attempt to create `Footer` from a sequence of bytes."] # [doc = ""] # [doc = " Errors:"] # [doc = " - `bytes` contains non-UTF-8 sequences"] # [doc = " - `bytes` does not decode as valid JSON"] # [doc = " - `bytes` top-most JSON object does not decode to a map"] # [doc = " - if any registered claims exist and they are not a `String`"] # [doc = " - Parsing JSON maps and arrays that are more than 128 layers deep"] # [doc = " - Maximum number of named keys is exceeded"] # [doc = " - Maximum JSON-encoded string length is exceeded"] pub fn parse_bytes (& mut self , bytes : & [u8]) -> Result < () , Error > { let input = bytes . to_vec () ; self . parse_string (& String :: from_utf8 (input) . map_err (| _ | Error :: FooterParsing) ?) } # [doc = " Attempt to parse a `Footer` from a string."] # [doc = ""] # [doc = " Errors:"] # [doc = " - `string` does not decode as valid JSON"] # [doc = " - `string` top-most JSON object does not decode to a map"] # [doc = " - if any registered claims exist and they are not a `String`"] # [doc = " - Parsing JSON maps and arrays that are more than 128 layers deep"] # [doc = " - Maximum number of named keys is exceeded"] # [doc = " - Maximum JSON-encoded string length is exceeded"] pub fn parse_string (& mut self , string : & str) -> Result < () , Error > { if string . len () > self . max_len { return Err (Error :: FooterParsing) ; } if Regex :: new (r#"[^\\]":"#) . unwrap () . find_iter (string) . count () > self . max_keys { return Err (Error :: FooterParsing) ; } self . list_of = serde_json :: from_str (string) . map_err (| _ | Error :: FooterParsing) ? ; Ok (()) } # [doc = " Return the JSON serialized representation of `Self`."] # [doc = ""] # [doc = " Errors:"] # [doc = " - `self` cannot be serialized as JSON"] pub fn to_string (& self) -> Result < String , Error > { match serde_json :: to_string (& self . list_of) { Ok (ret) => Ok (ret) , Err (_) => Err (Error :: FooterParsing) , } } }
